def num_comm_div(a, b):
    divisors_a = set()
    for i in range(1, a+1):
        if a % i == 0:
            divisors_a.add(i)

    divisors_b = set()
    for i in range(1, b+1):
        if b % i == 0:
            divisors_b.add(i)

    common_divisors = divisors_a.intersection(divisors_b)
    return len(common_divisors)

def permutation_coefficient(n, k):
    if k > n:
        return 0
    elif k == 0 or k == n:
        return 1
    else:
        return permutation_coefficient(n-1, k-1) * n

def count_element_freq(tup):
    freq_dict = {}
    for element in tup:
        if isinstance(element, tuple):
            for sub_element in element:
                freq_dict[sub_element] = freq_dict.get(sub_element, 0) + 1
        else:
            freq_dict[element] = freq_dict.get(element, 0) + 1
    return freq_dict
